package os.aios.core;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import java.io.*;import java.util.UUID;import org.json.*;import os.aios.core.events.EventHub;import os.aios.runtime.CoreRuntimeClient;
/** Single signature-protected structured gateway into system-level AIOS state owners. */
public final class CoreRuntimeProvider extends ContentProvider{
 public boolean onCreate(){CoreHostLifecycle.initializeProvider(getContext());return true;}
 public Bundle call(String domain,String action,Bundle extras){Bundle out=new Bundle();out.putInt("protocol_version",CoreRuntimeClient.PROTOCOL_VERSION);try{
  if(extras==null||extras.getInt("protocol_version")!=CoreRuntimeClient.PROTOCOL_VERSION)throw new IllegalArgumentException("Unsupported protocol");JSONObject p=new JSONObject(extras.getString("arguments","{}"));JSONObject result;
  switch(domain){
   case "capabilities":result=CoreCapabilities.call(getContext(),action,p);break;
   case "documents":if(!CoreState.authorized())throw new SecurityException("authorization_revoked");int documentUid=Binder.getCallingUid();if(documentUid!=os.aios.host.HostBindings.agentUid(getContext()))throw new SecurityException("agent_adapter_required");String documentThread=p.optString("_caller_thread");if(documentThread.isEmpty())throw new SecurityException("host_identity_required");result=CoreState.documents().call(action,p,documentUid+":"+documentThread);break;
   case "workspace":if(action.equals("recall.query")&&p.has("version")&&p.optInt("version")!=1&&p.optInt("version")!=2)throw new IllegalArgumentException("Unsupported recall version");if(os.aios.core.search.SearchCoordinator.handles(action,p)){if(!CoreState.authorized())throw new SecurityException("AIOS authorization disabled");String searchOwner=Binder.getCallingUid()+":"+p.optString("_caller_thread","workspace-ui");p.remove("_caller_thread");result=CoreState.search().call(action,p,searchOwner);}else result=CoreState.workspace().call(action,p);break;
   case "dream":result=CoreState.workspace().dream(action,p);break;
   case "automation":result=automation(action,p);break;
   case "events":result=events(action,p);break;
   case "inference":
    if(action.equals("status"))result=(CoreCapabilities.packaged("local-inference")?CoreFeatures.inference(getContext()).status():new JSONObject().put("state","not_packaged")).put("photo_models",CoreFeatureBindings.photoModelStatus(getContext()));
    else if(action.equals("generate")){if(!CoreState.authorized())throw new SecurityException("authorization_revoked");CoreCapabilities.require(getContext(),"local-inference");result=CoreFeatures.inference(getContext()).generate(p);}
    else throw new IllegalArgumentException("unknown_inference_action");
    break;
   case "processing":if(action.equals("album.status")){result=CoreState.automation().albumStatus();}else if(action.equals("album.configure")){result=CoreState.automation().configureAlbum(p);}else if(action.equals("dream.status")){result=DreamScheduler.status(getContext());}else if(action.equals("dream.schedule")){DreamScheduler.configure(getContext(),p.optBoolean("enabled",true),p.optBoolean("twice",false));result=new JSONObject().put("scheduled",p.optBoolean("enabled",true)).put("twice",p.optBoolean("twice",false));}else if(action.equals("dream.trigger")){DreamScheduler.manual(getContext());result=new JSONObject().put("queued",true);}else result=CoreState.processing().call(action,p);break;
   case "internal":result=internal(action,p);break;
   case "data":if(action.equals("allocate")){String id=UUID.randomUUID().toString();File file=dataFile(id);if(!file.getParentFile().mkdirs()&&!file.getParentFile().isDirectory())throw new IOException("Cannot create data channel");result=new JSONObject().put("id",id).put("uri","content://os.aios.core.runtime/data/"+id).put("expires_at",System.currentTimeMillis()+3600000);}else throw new IllegalArgumentException("Unknown data action");break;
   case "policy":if(action.equals("get"))result=new JSONObject().put("enabled",CoreState.authorized());else if(action.equals("set")){CoreState.setAuthorized(p.getBoolean("enabled"));CoreState.automation().reconcileAsync();result=new JSONObject().put("enabled",CoreState.authorized());}else throw new IllegalArgumentException("Unknown policy action");break;
   default:throw new IllegalArgumentException("Unknown Core Services domain: "+domain);
  }
  String json=result.toString();if(json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>524288)throw new IllegalStateException("Result exceeds structured IPC limit; use URI/FD data channel");out.putString("result",json);
 }catch(Exception e){out.putString("error",e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));}return out;}
 private JSONObject internal(String action,JSONObject p)throws Exception{if(action.startsWith("assistant.")){int uid=android.os.Binder.getCallingUid();if(uid!=os.aios.host.HostBindings.agentUid(getContext()))throw new SecurityException("Agent UID required");return CoreState.automation().assistantInternal(action.substring(10),p);}if(action.equals("skill.evidence"))return new JSONObject().put("id",CoreState.workspace().recordSkillEvidence(p));if(action.equals("execution.record"))return CoreState.workspace().recordExecution(p);throw new IllegalArgumentException("Unknown internal action");}
 private JSONObject automation(String action,JSONObject p)throws Exception{if(action.equals("authorization.put"))return CoreState.automation().putAuthorization(p);if(action.equals("reconcile")){CoreState.automation().reconcileAsync();return new JSONObject().put("scheduled",true);}return CoreState.automation().call(action,p);}
 private JSONObject events(String action,JSONObject p)throws Exception{switch(action){case "publish":JSONObject event=EventHub.publish(p.optString("id",null),p.getString("topic"),p.getString("source_id"),p.getString("source_version"),p.getJSONObject("data"),p.optBoolean("critical"));JSONObject dispatch=new JSONObject().put("topic",p.getString("topic")).put("data",p.getJSONObject("data")).put("event",event);return event.put("scheduler",CoreState.automation().onEvent(dispatch));case "read":return EventHub.read(p.optLong("after"));case "subscribe":return EventHub.subscribe(p.getJSONArray("topics"));case "poll":return EventHub.poll(p.getString("subscription"));case "ack":return EventHub.ack(p.getString("subscription"),p.getJSONArray("events"));case "fail":return EventHub.fail(p.getString("subscription"),p.getString("event_id"),p.getString("error"));case "unsubscribe":return EventHub.unsubscribe(p.getString("subscription"));default:throw new IllegalArgumentException("Unknown Event Hub action");}}
 private File dataFile(String id){if(!id.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("Invalid data id");return new File(new File(getContext().getCacheDir(),"channels"),id);}
 @Override public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{
  if(u.getPathSegments().size()==2&&java.util.Set.of("photo","file").contains(u.getPathSegments().get(0))){
   if(!mode.equals("r")||!CoreState.authorized())throw new FileNotFoundException("Photo read not authorized");
   try{String id=u.getLastPathSegment();if(id==null||!id.matches("[0-9]{1,19}"))throw new IllegalArgumentException("Invalid photo id");os.aios.runtime.DeviceSearchClient client=new os.aios.runtime.DeviceSearchClient(getContext());JSONObject args=new JSONObject().put("source",u.getPathSegments().get(0).equals("photo")?"photos":"files").put("id",id);org.json.JSONArray rows=client.call("get",args).getJSONArray("items");if(rows.length()!=1)throw new SecurityException("Photo unavailable");String version=rows.getJSONObject(0).getString("source_version");if(!version.equals(u.getQueryParameter("version")))throw new IllegalStateException("Photo changed; refresh search");return client.open(args.put("source_version",version));}catch(Exception e){FileNotFoundException failure=new FileNotFoundException(e.getMessage());failure.initCause(e);throw failure;}
  }
if(u.getPathSegments().size()!=2||!u.getPathSegments().get(0).equals("data"))throw new FileNotFoundException();File f=dataFile(u.getLastPathSegment());int flags=mode.equals("r")?ParcelFileDescriptor.MODE_READ_ONLY:ParcelFileDescriptor.MODE_CREATE|ParcelFileDescriptor.MODE_TRUNCATE|ParcelFileDescriptor.MODE_WRITE_ONLY;return ParcelFileDescriptor.open(f,flags);}
 public Cursor query(Uri u,String[]p,String s,String[]a,String o){
  if(u.getPathSegments().size()!=2||!java.util.Set.of("photo","file").contains(u.getPathSegments().get(0)))throw new UnsupportedOperationException();
  if(!CoreState.authorized())throw new SecurityException("authorization_revoked");
  try{JSONObject response=new os.aios.runtime.DeviceSearchClient(getContext()).call("get",new JSONObject().put("source",u.getPathSegments().get(0).equals("file")?"files":"photos").put("id",u.getLastPathSegment()));JSONArray rows=response.getJSONArray("items");if(rows.length()!=1)throw new SecurityException("source_unavailable");JSONObject row=rows.getJSONObject(0);if(!row.getString("source_version").equals(u.getQueryParameter("version")))throw new IllegalStateException("source_changed");String[] columns=p==null?new String[]{"_display_name","_size"}:p;android.database.MatrixCursor cursor=new android.database.MatrixCursor(columns);Object[] values=new Object[columns.length];for(int i=0;i<columns.length;i++){if(columns[i].equals("_display_name"))values[i]=row.getString("title");else if(columns[i].equals("_size"))values[i]=row.getJSONObject("fields").opt("_size");}cursor.addRow(values);return cursor;}catch(Exception e){throw new IllegalStateException("document_unavailable",e);}
 }public String getType(Uri u){return u.getPathSegments().size()==2&&u.getPathSegments().get(0).equals("photo")?"image/*":"application/octet-stream";}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[]a){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[]a){if(u.getPathSegments().size()==2&&u.getPathSegments().get(0).equals("data"))return dataFile(u.getLastPathSegment()).delete()?1:0;throw new UnsupportedOperationException();}
}
